"""Generate the responsive classroom guide; Python Markdown or Pandoc is required."""
from pathlib import Path
import re
import shutil
import subprocess
import html

ROOT = Path(__file__).resolve().parents[1]
source = ROOT / 'docs/guia-da-turma.md'
text = source.read_text(encoding='utf-8-sig').split('\n', 1)[1]
try:
    import markdown
    converter = markdown.Markdown(extensions=['tables', 'fenced_code', 'toc'], extension_configs={'toc': {'toc_depth': '2-2'}})
    content = converter.convert(text)
    toc = converter.toc
except ImportError:
    if not shutil.which('pandoc'):
        raise SystemExit('Instale Python Markdown ou Pandoc para atualizar o HTML do guia.')
    content = subprocess.check_output(['pandoc', '-f', 'gfm', '-t', 'html5'], input=text, text=True, encoding='utf-8')
    headings = re.findall(r'<h2 id="([^"]+)">(.*?)</h2>', content, re.S)
    toc = '<ul>' + ''.join('<li><a href="#'+i+'">'+t+'</a></li>' for i,t in headings) + '</ul>'
# Link the HTML guide back to the portal and browser-ready versions where present.
for target in re.findall(r'href="([^"]+\.md)"', content):
    path = (source.parent / target).resolve()
    rendered = path.with_name('index.html') if path.name == 'README.md' else path.with_suffix('.html')
    if rendered.is_file():
        import os
        relative = Path(os.path.relpath(rendered, source.parent)).as_posix()
        content = content.replace('href="'+target+'"', 'href="'+html.escape(relative, quote=True)+'"')
css = '''
:root{--ink:#19382f;--muted:#52675d;--green:#235c46;--line:#d7e3d9;--paper:#fff;--wash:#f3f7f2;--accent:#d7edb5}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--wash);color:var(--ink);font:17px/1.75 system-ui,-apple-system,Segoe UI,sans-serif}a{color:var(--green);text-underline-offset:4px;overflow-wrap:anywhere}a:hover{text-decoration-thickness:2px}:focus-visible{outline:3px solid #b36a17;outline-offset:5px}.skip{position:absolute;top:-100px;left:16px;background:white;padding:12px;z-index:10}.skip:focus{top:10px}.topbar{background:#fff;border-bottom:1px solid var(--line)}.topbar nav{max-width:1320px;margin:auto;padding:18px 24px;display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap}.brand{font-weight:800;text-decoration:none}.toplinks{display:flex;gap:20px;flex-wrap:wrap;font-size:14px}.hero{background:var(--ink);color:white}.hero-inner{max-width:1320px;margin:auto;padding:58px 24px 45px}.eyebrow{font-size:12px;font-weight:750;letter-spacing:.12em;color:#d2e5c4}h1{font-size:clamp(32px,5vw,56px);line-height:1.15;letter-spacing:-.035em;max-width:850px;margin:18px 0}h1+p{max-width:740px;font-size:20px;color:#e2ece4}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:26px 0}.button{display:inline-block;border:1px solid #d5e5cd;border-radius:10px;padding:11px 18px;font:inherit;font-weight:700;text-decoration:none;cursor:pointer;background:var(--accent);color:var(--ink)}.button.secondary{background:transparent;color:white}.hero small{color:#d2e5c4}.journey{display:flex;flex-wrap:wrap;gap:9px;list-style:none;padding:0;margin:24px 0 0}.journey li{font-size:14px;border:1px solid #547166;border-radius:24px;padding:6px 13px}.layout{max-width:1320px;margin:auto;padding:35px 24px 70px;display:grid;grid-template-columns:265px minmax(0,1fr);gap:36px;align-items:start}aside{position:sticky;top:22px;max-height:90vh;overflow:auto;background:white;border:1px solid var(--line);border-radius:16px;padding:20px}summary{font-weight:750;cursor:pointer}.toc ul{padding-left:18px;margin-bottom:0}.toc li{margin:11px 0;font-size:14px;line-height:1.5}.toc a{text-decoration:none}article{min-width:0;background:var(--paper);padding:32px clamp(18px,3vw,42px);border:1px solid var(--line);border-radius:18px;overflow-wrap:anywhere}article>p:first-child{font-size:19px}h2{font-size:clamp(24px,3vw,30px);line-height:1.3;margin:48px 0 20px;padding-top:18px;border-top:1px solid var(--line);letter-spacing:-.02em}h3{font-size:21px;line-height:1.4;margin-top:30px}li{margin:9px 0}li p{margin:8px 0}blockquote{margin:25px 0;background:#eef5e5;border-left:4px solid #527a36;padding:16px 22px;border-radius:0 10px 10px 0}blockquote p:first-child{margin-top:0}blockquote p:last-child{margin-bottom:0}pre{background:#172e26;color:#f0f6ec;padding:20px;border-radius:12px;overflow:auto;max-width:100%;font:14px/1.7 ui-monospace,Consolas,monospace}code{font-family:ui-monospace,Consolas,monospace;font-size:.88em}p code,li code,td code{background:#edf2e8;padding:2px 5px;border-radius:4px;word-break:break-word}.table-scroll{overflow-x:auto;max-width:100%;margin:22px 0;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;font-size:15px}th,td{padding:13px 15px;vertical-align:top;text-align:left;border-bottom:1px solid var(--line);min-width:150px}th{background:#eaf2e2}tr:last-child td{border-bottom:0}.footer{max-width:1320px;margin:auto;padding:25px 24px 40px;font-size:14px;color:var(--muted);border-top:1px solid var(--line)}.footer a{margin-right:14px}@media(max-width:900px){.layout{grid-template-columns:1fr;gap:20px}aside{position:static;max-height:none}.hero-inner{padding-top:38px}.layout{padding:22px 16px 45px}article{border-radius:12px}.topbar nav{padding:15px 18px}.toplinks{gap:12px}h1+p{font-size:18px}.journey li{font-size:13px}}@media(max-width:420px){body{font-size:16px}.hero-inner{padding-left:18px;padding-right:18px}.button{width:100%;text-align:center}.actions{width:100%}.toplinks{font-size:13px}article{padding:22px 16px}th,td{min-width:130px;padding:10px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{.topbar,aside,.actions,.skip,.journey{display:none}.hero,.hero-inner{background:white;color:black;padding:0}.hero p,.hero small,.eyebrow{color:black}.layout{display:block;padding:0}body,article{background:white;color:black}article{border:0;padding:0}h2,h3{break-after:avoid}pre,blockquote{background:#f2f2f2;color:black}pre{white-space:pre-wrap}a{color:inherit}.table-scroll{overflow:visible}table{font-size:12px}.footer{margin-top:25px}}
'''
content = re.sub(r'(<table>.*?</table>)', r'<div class="table-scroll" role="region" aria-label="Tabela de orientações" tabindex="0">\1</div>', content, flags=re.S)
page = '''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Guia para colegas de turma e de trabalho: aprenda a acessar o repositório, criar sua cópia e contribuir pelo navegador, passo a passo."><title>Guia da Turma — aprender e contribuir juntos | 4ABL</title><style>'''+css+'''</style></head>
<body><a class="skip" href="#conteudo">Ir para o conteúdo</a><header class="topbar"><nav aria-label="Navegação principal"><a class="brand" href="../index.html">MBA AI Leadership · 4ABL</a><div class="toplinks"><a href="../index.html">Página principal</a><a href="../README.md">README</a><a href="guia-da-turma.md">Versão em texto</a></div></nav></header>
<section class="hero" aria-labelledby="titulo"><div class="hero-inner"><span class="eyebrow">PARA COLEGAS DE TURMA E DE TRABALHO</span><h1 id="titulo">Vamos aprender e construir juntos.</h1><p>Seu primeiro passo para estudar, experimentar e compartilhar descobertas. Comece pelo navegador, no seu ritmo e sem precisar saber programar.</p><div class="actions"><a class="button" href="#conteudo">Começar pelo guia ↓</a><a class="button secondary" href="https://github.com/ProfAntonioFigueiredo/mba-ai-leadership-4abl">Abrir o repositório</a><button class="button secondary" type="button" onclick="window.print()">Imprimir ou salvar PDF</button></div><small>Um espaço para todas as disciplinas e para quem quer aprender com a gente.</small><ol class="journey" aria-label="Caminho da contribuição"><li>1 · Acessar</li><li>2 · Criar sua cópia</li><li>3 · Fazer a atividade</li><li>4 · Compartilhar</li></ol></div></section>
<main class="layout"><aside><details id="menu" open><summary>Encontre seu próximo passo</summary><nav aria-label="Seções do guia">'''+toc+'''</nav></details></aside><article id="conteudo" tabindex="-1" aria-label="Guia passo a passo">'''+content+'''</article></main><footer class="footer"><p>Este guia pode ser aberto no computador ou no celular. Para compartilhar um endereço que abra como página, o portal precisa estar hospedado; a visualização de arquivos HTML no GitHub mostra o código.</p><a href="../index.html">← Voltar à página principal</a><a href="guia-da-turma.md">Consultar o texto original</a></footer><script>const menu=document.querySelector('#menu');const mobile=window.matchMedia('(max-width:900px)');function adapt(){menu.open=!mobile.matches;}adapt();mobile.addEventListener('change',adapt);</script></body></html>'''
(ROOT / 'docs/guia-da-turma.html').write_text(page, encoding='utf-8')
print('Guia HTML atualizado: docs/guia-da-turma.html')
